<?php
require __DIR__.'/app-bootstrap.php';require_admin();require_once dirname(__DIR__).'/private/src/admin_layout.php';
$days=max(1,min(365,(int)($_GET['days']??30)));$since=date('Y-m-d H:i:s',time()-$days*86400);$rows=[];$sections=[];$available=true;
try{$st=$pdo->prepare("SELECT t.id,t.title,GROUP_CONCAT(DISTINCT a.name ORDER BY ta.sort_order,a.name SEPARATOR ' x ') artist_name,SUM(e.event_type='play') plays,SUM(e.event_type='complete') completions,SUM(e.event_type='skip') skips,SUM(e.event_type='seek') seeks,COUNT(DISTINCT CASE WHEN o.status='paid' AND e.user_id IS NOT NULL AND o.paid_at>=e.created_at THEN CONCAT(e.user_id,'-',o.id) END) buyers FROM tracks t LEFT JOIN track_artists ta ON ta.track_id=t.id LEFT JOIN artists a ON a.id=ta.artist_id LEFT JOIN preview_events e ON e.track_id=t.id AND e.created_at>=? LEFT JOIN order_items oi ON oi.track_id=t.id LEFT JOIN orders o ON o.id=oi.order_id GROUP BY t.id,t.title ORDER BY plays DESC,t.title");$st->execute([$since]);$rows=$st->fetchAll();$st=$pdo->prepare("SELECT t.title,GROUP_CONCAT(DISTINCT a.name ORDER BY ta.sort_order,a.name SEPARATOR ' x ') artist_name,e.section_seconds,COUNT(*) hits FROM preview_events e JOIN tracks t ON t.id=e.track_id LEFT JOIN track_artists ta ON ta.track_id=t.id LEFT JOIN artists a ON a.id=ta.artist_id WHERE e.event_type='seek' AND e.created_at>=? GROUP BY e.track_id,e.section_seconds,t.title ORDER BY hits DESC LIMIT 30");$st->execute([$since]);$sections=$st->fetchAll();}catch(Throwable $e){$available=false;}
admin_layout_start('Preview analytics','preview-analytics');
?><div class="section-title"><div><span class="kicker">LISTENER INSIGHTS</span><h1>Preview analytics</h1></div><form class="report-period-form" method="get"><label>Period<select name="days" onchange="this.form.submit()"><option value="7" <?=$days===7?'selected':''?>>Last 7 days</option><option value="30" <?=$days===30?'selected':''?>>Last 30 days</option><option value="90" <?=$days===90?'selected':''?>>Last 90 days</option><option value="365" <?=$days===365?'selected':''?>>Last 12 months</option></select></label></form></div>
<?php if(!$available):?><div class="panel error">Preview analytics is unavailable until the canonical database schema has been installed.</div><?php else:?><section class="panel"><div class="admin-section-head"><h2>Track previews</h2><span>Plays, completions, skips, seeks and purchases</span></div><div class="admin-table preview-analytics-table"><div class="admin-row preview-analytics-head"><strong>Track</strong><strong>Plays</strong><strong>Complete</strong><strong>Rate</strong><strong>Skips</strong><strong>Seeks</strong><strong>Buyers</strong><strong>Conversion</strong></div><?php foreach($rows as $row):$plays=(int)$row['plays'];$buyers=(int)$row['buyers'];?><div class="admin-row"><span><strong><?=e($row['title'])?></strong><small><?=e($row['artist_name']?:'—')?></small></span><span><?=$plays?></span><span><?=e((string)$row['completions'])?></span><span><?=e($plays?round(((int)$row['completions']/$plays)*100,1):0)?>%</span><span><?=e((string)$row['skips'])?></span><span><?=e((string)$row['seeks'])?></span><span><?=$buyers?></span><span><?=e($plays?round(($buyers/$plays)*100,1):0)?>%</span></div><?php endforeach;?><?php if(!$rows):?><p class="muted">No preview events have been recorded in this period.</p><?php endif;?></div><p class="muted">Conversion counts paid orders from signed-in users who previewed the track during this period.</p></section><section class="panel"><div class="admin-section-head"><h2>Most-seeked sections</h2><span>10-second buckets</span></div><div class="admin-table preview-analytics-table"><div class="admin-row preview-analytics-head"><strong>Track</strong><strong>Section</strong><strong>Seeks</strong></div><?php foreach($sections as $row):?><div class="admin-row"><span><strong><?=e($row['title'])?></strong><small><?=e($row['artist_name']?:'—')?></small></span><span><?=e((string)$row['section_seconds'])?>–<?=e((string)((int)$row['section_seconds']+10))?> seconds</span><span><?=e((string)$row['hits'])?></span></div><?php endforeach;?><?php if(!$sections):?><p class="muted">No seek events have been recorded in this period.</p><?php endif;?></div></section><?php endif;?><?php admin_layout_end();
